const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const geom = ee.Geometry.Rectangle([79.8, 37.5, 80.0, 37.7]); // Taklamakan Desert near Hotan
    const date1Str = '2020-02-23';
    const date2Str = '2020-04-29';
    const date1 = ee.Date(date1Str);
    const date2 = ee.Date(date2Str);

    // Helpers
    const evaluate = (obj) =>
      new Promise((resolve, reject) => obj.evaluate((v, e) => (e ? reject(e) : resolve(v))));
    const fmtDate = (d) => {
      const iso = d.toISOString();
      return iso ? iso.slice(0, 10) : null;
    };

    // Masks
    function maskS2(img) {
      const qa = img.select('QA60');
      const cloud = qa.bitwiseAnd(1 << 10).eq(0);
      const cirrus = qa.bitwiseAnd(1 << 11).eq(0);
      return img.updateMask(cloud.and(cirrus));
    }
    function ndviS2(img) {
      return img.select(['B8', 'B4']).rename(['nir', 'red']).normalizedDifference(['nir', 'red']).rename('ndvi');
    }
    function maskL8L2(img) {
      const qa = img.select('QA_PIXEL');
      const mask = qa
        .bitwiseAnd(1 << 3).eq(0) // cloud shadow
        .and(qa.bitwiseAnd(1 << 4).eq(0)) // snow
        .and(qa.bitwiseAnd(1 << 5).eq(0)) // cloud
        .and(qa.bitwiseAnd(1 << 7).eq(0)); // water
      return img.updateMask(mask);
    }
    function ndviL8(img) {
      const scaled = img.select(['SR_B5', 'SR_B4']).multiply(0.0000275).add(-0.2);
      return scaled.normalizedDifference(['SR_B5', 'SR_B4']).rename('ndvi');
    }

    // Collections
    function getS2Col(start, end) {
      return ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(geom)
        .filterDate(start, end)
        .filter(ee.Filter.lte('CLOUDY_PIXEL_PERCENTAGE', 60))
        .map(maskS2);
    }
    function getL8Col(start, end) {
      return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
        .filterBounds(geom)
        .filterDate(start, end)
        .filter(ee.Filter.lte('CLOUD_COVER', 70))
        .map(maskL8L2);
    }

    // Select best image near a date with fallback strategy
    async function getBestImageNear(date, label) {
      // Step 1: S2 ±3 days
      let win = 3;
      let start = date.advance(-win, 'day');
      let end = date.advance(win + 1, 'day');
      let s2col = getS2Col(start, end);
      let s2count3 = await evaluate(s2col.size());

      // For concise evidence, we'll print counts for ±3 once for both dates outside this function.

      // If none, widen to ±10
      let sourceInfo = null;
      if (s2count3 > 0) {
        sourceInfo = { source: 'S2±3d' };
      } else {
        win = 10;
        start = date.advance(-win, 'day');
        end = date.advance(win + 1, 'day');
        s2col = getS2Col(start, end);
        const s2count10 = await evaluate(s2col.size());
        if (s2count10 > 0) {
          sourceInfo = { source: 'S2±10d' };
        }
      }

      if (sourceInfo) {
        const target = date.millis();
        const best = s2col
          .map(function (img) {
            const diff = img.date().difference(date, 'day').abs();
            return img.set('diff', diff);
          })
          .sort('CLOUDY_PIXEL_PERCENTAGE')
          .sort('diff')
          .first();
        const img = ee.Image(best);
        const ndvi = ndviS2(img);
        const imgDate = await evaluate(img.date());
        const cloudPct = await evaluate(img.get('CLOUDY_PIXEL_PERCENTAGE'));
        return {
          image: img,
          ndvi: ndvi,
          src: sourceInfo.source,
          imgDateStr: fmtDate(new Date(imgDate.value)),
          cloudPct: cloudPct,
          platform: 'S2'
        };
      }

      // Fallback: Landsat 8 ±10 days
      win = 10;
      start = date.advance(-win, 'day');
      end = date.advance(win + 1, 'day');
      let l8col = getL8Col(start, end);
      const l8count = await evaluate(l8col.size());
      if (l8count === 0) {
        return { image: null, reason: 'C1' };
      }
      const bestL8 = l8col
        .map(function (img) {
          const diff = img.date().difference(date, 'day').abs();
          return img.set('diff', diff);
        })
        .sort('CLOUD_COVER')
        .sort('diff')
        .first();
      const l8img = ee.Image(bestL8);
      const l8ndvi = ndviL8(l8img);
      const l8date = await evaluate(l8img.date());
      const l8cloud = await evaluate(l8img.get('CLOUD_COVER'));
      return {
        image: l8img,
        ndvi: l8ndvi,
        src: 'L8±10d',
        imgDateStr: fmtDate(new Date(l8date.value)),
        cloudPct: l8cloud,
        platform: 'L8'
      };
    }

    // Print initial S2 ±3d collection sizes for both dates (data availability check)
    const s2count1 = await evaluate(
      getS2Col(date1.advance(-3, 'day'), date1.advance(4, 'day')).size()
    );
    const s2count2 = await evaluate(
      getS2Col(date2.advance(-3, 'day'), date2.advance(4, 'day')).size()
    );
    console.log('Region: Taklamakan near Hotan [79.8–80.0E, 37.5–37.7N]');
    console.log(`S2 images ±3d — 2020-02-23: ${s2count1}, 2020-04-29: ${s2count2}`);

    // Get best images
    const img1 = await getBestImageNear(date1, 't1');
    const img2 = await getBestImageNear(date2, 't2');

    if (!img1.image || !img2.image) {
      console.log('One or both dates: no images after fallbacks.');
      console.log('C1');
      return;
    }

    // Compute stats for each date
    async function computeStats(ndvi) {
      const veg = ndvi.gt(0.2).rename('veg').updateMask(ndvi.mask());
      const countDict = ndvi.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      });
      const fracDict = veg.reduceRegion({
        reducer: ee.Reducer.mean(),
        geometry: geom,
        scale: 1000,
        maxPixels: 1e9
      });
      const count = await evaluate(countDict.get('ndvi'));
      const frac = await evaluate(fracDict.get('veg'));
      return { count, frac };
    }

    const stats1 = await computeStats(img1.ndvi);
    const stats2 = await computeStats(img2.ndvi);

    // Case handling
    if (!stats1 || !stats2) {
      console.log('Computation returned null stats.');
      console.log('C3');
      return;
    }
    const c1 = stats1.count || 0;
    const c2 = stats2.count || 0;

    if (c1 === 0 || c2 === 0) {
      console.log('No valid pixels after masking for one or both dates.');
      console.log('C2');
      return;
    }
    if (stats1.frac === null || stats2.frac === null) {
      console.log('Vegetation fraction is null.');
      console.log('C3');
      return;
    }
    if (!isFinite(stats1.frac) || !isFinite(stats2.frac) || stats1.frac < 0 || stats2.frac < 0 || stats1.frac > 1.2 || stats2.frac > 1.2) {
      console.log('Vegetation fraction invalid.');
      console.log('C3');
      return;
    }

    // Prepare concise evidence outputs
    const vegPct1 = 100 * Math.max(0, Math.min(1, stats1.frac));
    const vegPct2 = 100 * Math.max(0, Math.min(1, stats2.frac));
    const vegCells1 = Math.round((vegPct1 / 100) * c1);
    const vegCells2 = Math.round((vegPct2 / 100) * c2);

    console.log(
      `2020-02-23 source: ${img1.src}, imgDate: ${img1.imgDateStr}, cloud%: ${img1.cloudPct !== null ? img1.cloudPct.toFixed(1) : 'NA'}`
    );
    console.log(`2020-04-29 source: ${img2.src}, imgDate: ${img2.imgDateStr}, cloud%: ${img2.cloudPct !== null ? img2.cloudPct.toFixed(1) : 'NA'}`);

    console.log(`2020-02-23 valid px(1km): ${c1}, veg px: ${vegCells1}, veg%: ${vegPct1.toFixed(2)}`);
    console.log(`2020-04-29 valid px(1km): ${c2}, veg px: ${vegCells2}, veg%: ${vegPct2.toFixed(2)}`);

    const diff = vegPct2 - vegPct1;
    console.log(`Δ veg% (Apr29 - Feb23): ${diff.toFixed(2)}`);

    // Decision threshold
    const threshold = 0.1; // percentage points
    if (!isFinite(diff)) {
      console.log('C3');
      return;
    }
    if (diff > threshold) {
      console.log('A');
    } else {
      console.log('B');
    }
  } catch (err) {
    console.log('Processing error:', err && err.message ? err.message : String(err));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
